// Vocabulary terms are drawn from Raven's printed glossary; definitions are cleaned for flashcard use.
(function () {
  const additions = [{"chapter":1,"cards":[{"front":"acid","back":"A substance that dissociates in water, releasing hydrogen ions (H+) and thus causing a relative increase in the concentration of these ions; a substance with a pH, in solution, of less than 7; a proton donor; the opposite of base."},{"front":"annual","back":"A plant whose life cycle is completed in a single growing season."},{"front":"base","back":"A substance that dissociates in water, causing a decrease in the concentration of hydrogen ions (H+), often by releasing hydroxyl ions (OH–); having a pH, in solution, of more than 7; the opposite of acid. Also called an alkali."},{"front":"endomembrane system","back":"Collectively, the cellular membranes that form a continuum (plasma membrane, tonoplast, endoplasmic reticulum, Golgi bodies, and nuclear envelope)."},{"front":"leaf trace","back":"That part of a vascular bundle extending from the base of the leaf to its connection with a vascular bundle in the stem."},{"front":"mineral","back":"A naturally occurring chemical element or inorganic compound."},{"front":"perennial","back":"A plant in which the vegetative structures live year after year."},{"front":"root","back":"The usually descending axis of a plant, normally below ground, which serves to anchor the plant and to absorb and conduct water and minerals into it."},{"front":"simple leaf","back":"An undivided leaf; as opposed to a compound leaf."},{"front":"stem","back":"The part of the axis of vascular plants that is above ground, as well as anatomically similar portions below ground, such as rhizomes or corms."},{"front":"vascular system","back":"All the vascular tissues in their specific arrangement in a plant or plant organ."},{"front":"xylem","back":"A complex vascular tissue through which most of the water and minerals of a plant are conducted; characterized by the presence of tracheary elements."},{"front":"homeotic genes","back":"Genes affecting floral organ identity."},{"front":"leaf scar","back":"A scar left on a twig when a leaf falls."},{"front":"leaflet","back":"One of the parts of a compound leaf."},{"front":"morphogenesis","back":"The development of form."},{"front":"stem bundle","back":"Vascular bundle belonging to the stem."}]},{"chapter":2,"cards":[{"front":"carbohydrate","back":"An organic compound consisting of a chain of carbon atoms to which hydrogen and oxygen are attached in a 2:1 ratio (CH O); examples are sugars, starch, glycogen, and 2 cellulose."},{"front":"channel proteins","back":"Transport proteins that form water-filled pores that extend across cellular membranes; when open, channel proteins allow specific solutes to pass through them."},{"front":"cutin","back":"Fatty substance deposited in many plant cell walls and on the outer surface of epidermal cell walls, where it forms a layer known as the cuticle."},{"front":"hemicellulose","back":"A polysaccharide resembling cellulose but more soluble and less ordered; found particularly in cell walls."},{"front":"integral proteins","back":"Transmembrane proteins and other proteins that are tightly bound to the membrane."},{"front":"lignin","back":"One of the most important constituents of the secondary wall of vascular plants, although not all secondary walls contain lignin; after cellulose, lignin is the most abundant plant polymer."},{"front":"macromolecule","back":"A molecule of very high molecular weight; refers specifically to proteins, nucleic acids, polysaccharides, and complexes of these."},{"front":"molecule","back":"Smallest possible unit of a compound, consisting of two or more atoms."},{"front":"monosaccharide","back":"A simple sugar, such as a five-carbon or six-carbon sugar, that cannot be dissociated into smaller sugar particles."},{"front":"nitrogenous base","back":"A nitrogen-containing molecule having basic properties (tendency to acquire an H+ ion); a purine or pyrimidine; one of the building blocks of nucleic acids."},{"front":"phospholipid","back":"A phosphorylated lipid; similar in structure to a fat, but with only two fatty acids attached to the glycerol backbone, with the third space occupied by a phosphorus-containing molecule; phospholipids are important components of cellular membranes."},{"front":"polar molecule","back":"A molecule with positively and negatively charged ends."},{"front":"polysaccharide","back":"A polymer composed of many monosaccharide units joined in a long chain, such as glycogen, starch, and cellulose. Glossary G–19"},{"front":"protein","back":"A complex organic compound composed of many (100 or more) amino acids joined by peptide bonds."},{"front":"structural gene","back":"Any gene that codes for a protein; as opposed to a regulatory gene."},{"front":"transmembrane proteins","back":"Globular proteins that traverse the lipid bilayer of cellular membranes; some extend across the lipid bilayer as a single alpha helix, others as multiple alpha helices."},{"front":"transport protein","back":"A specific membrane protein responsible for transferring solutes across membranes; transport proteins are grouped into three broad"}]},{"chapter":3,"cards":[{"front":"mitosis","back":"A process during which the duplicated chromosomes divide longitudinally and the daughter chromosomes then separate to form two genetically identical daughter nuclei; usually accompanied by cytokinesis."},{"front":"amyloplast","back":"A leucoplast (colorless plastid) that forms starch grains."},{"front":"cytokinesis","back":"Division of the cytoplasm of a cell following nuclear division."},{"front":"cytoskeleton","back":"The flexible network within cells, composed of microtubules and actin filaments, or microfilaments."},{"front":"cytosol","back":"The cytoplasmic matrix of the cytoplasm in which the nucleus, various organelles, and membrane systems are suspended."},{"front":"etioplast","back":"Plastid of a plant grown in the dark and containing a prolamellar body."},{"front":"leucoplast","back":"A colorless plastid; leucoplasts are commonly centers of starch formation."},{"front":"lumen","back":"(1) The space bounded by the plant cell wall; (2) the thylakoid space in chloroplasts; (3) the narrow, transparent space of endoplasmic reticulum."},{"front":"microfilament","back":"A helical protein filament, 5 to 7 nanometers thick, composed of globular actin molecules; a major constituent of the cytoskeleton of all eukaryotic cells. Also called a microfilament."},{"front":"middle lamella","back":"The layer of intercellular material, rich in pectic compounds, cementing together the primary walls of adjacent cells."},{"front":"organelle","back":"A specialized, membrane- bounded part of a cell."},{"front":"plasmodesma","back":"The minute cytoplasmic threads that extend through openings in cell walls and connect the protoplasts of adjacent living cells."},{"front":"plastid","back":"Organelle in the cells of certain groups of eukaryotes that is the site of such activities as food manufacture and storage; plastids are bounded by two membranes."},{"front":"proplastid","back":"A minute, self-reproducing body in the cytoplasm from which a plastid develops. G–20 Glossary"},{"front":"vacuole","back":"A space or cavity within the cytoplasm filled with a watery fluid, the cell sap; a lysosomal compartment."}]},{"chapter":4,"cards":[{"front":"active transport","back":"Energy-requiring transport of a solute across a membrane in the direction of increasing concentration (against the concentration gradient)."},{"front":"diffusion","back":"The net movement of suspended or dissolved particles from a more concentrated region to a less concentrated region as a result of the random movement of individual molecules; the process tends to distribute such particles uniformly throughout a medium."},{"front":"facilitated diffusion","back":"Passive transport with the assistance of carrier proteins."},{"front":"aquaporins","back":"Integral membrane proteins that form water channels across the membrane, facilitating the movement of water and/or small neutral solutes or gases across the membrane."},{"front":"endocytosis","back":"The uptake of material into cells by means of invagination of the plasma membrane; if solid material is involved, the process is called phagocytosis; if dissolved material is involved, it is called pinocytosis."},{"front":"exocytosis","back":"A cellular process in which particulate matter or dissolved substances are enclosed in a vesicle and transported to the cell surface; there, the membrane of the vesicle fuses with the plasma membrane, expelling the vesicle’s contents to the outside."},{"front":"turgor pressure","back":"Pressure within the cell resulting from the movement of water into the cell."},{"front":"acid growth hypothesis","back":"The hypothesis that acidification of the cell wall leads to hydrolysis of restraining bonds within the wall and, consequently, to cell elongation driven by the turgor pressure on the wall."}]},{"chapter":5,"cards":[{"front":"allosteric interaction","back":"A change in the shape of a protein resulting from binding to the protein of a nonsubstrate molecule; in its new shape, the protein typically has different properties."},{"front":"catalyst","back":"A substance that accelerates the rate of a chemical reaction but is not used up in the reaction; enzymes are catalysts."},{"front":"coenzyme","back":"An organic molecule, or nonprotein organic cofactor, that plays an accessory role in enzyme-catalyzed processes, often by acting as a donor or acceptor of electrons; NAD+ and FAD are common coenzymes."},{"front":"endergonic","back":"Describing a chemical reaction that requires energy to proceed; the opposite of exergonic."},{"front":"enzyme","back":"A protein that is capable of speeding up specific chemical reactions by lowering the required activation energy but is itself unaltered in the process; a biological catalyst."},{"front":"exergonic","back":"Energy-yielding, as in a chemical reaction; applied to a “downhill” process."},{"front":"free energy","back":"Energy available to do work."},{"front":"oxidation","back":"The loss of an electron by an atom or molecule. Oxidation and reduction (gain of an electron) take place simultaneously, because an electron that is lost by one atom is accepted by another. Oxidation-reduction reactions are an important means of energy transfer in living systems."}]},{"chapter":6,"cards":[{"front":"aerobic respiration","back":"An intracellular process in which molecules, particularly pyruvate entering the citric acid cycle, are oxidized with the release of energy. The complete breakdown of sugar or other organic compounds to carbon dioxide and water is termed aerobic respiration, although the first steps of the process are anaerobic. Also called cellular respiration."},{"front":"cellular respiration","back":"An intracellular process in which molecules, particularly pyruvate entering the citric acid cycle, are oxidized with the release of energy. The complete breakdown of sugar or other organic compounds to carbon dioxide and water is termed aerobic respiration, although the first steps of the process are anaerobic. Also called cellular respiration."},{"front":"respiration","back":"An intracellular process in which molecules, particularly pyruvate entering the citric acid cycle, are oxidized with the release of energy. The complete breakdown of sugar or other organic compounds to carbon dioxide and water is termed aerobic respiration, although the first steps of the process are anaerobic. Also called cellular respiration."},{"front":"citric acid cycle","back":"The series of reactions that results in the oxidation of pyruvate to hydrogen atoms, electrons, and carbon dioxide. The electrons, passed along electron-carrier molecules, then go through the oxidative phosphorylation and terminal oxidation processes. Also called the Krebs cycle or tricarboxylic acid cycle."},{"front":"glycolysis","back":"The anaerobic breakdown of glucose to form two molecules of pyruvate, resulting in the net formation of two molecules of ATP; catalyzed by enzymes in the cytosol."},{"front":"oxidative phosphorylation","back":"The formation of ATP from ADP and inorganic phosphate; takes place in the electron transport chain of the mitochondrion."},{"front":"tricarboxylic acid cycle","back":"The series of reactions that results in the oxidation of pyruvate to hydrogen atoms, electrons, and carbon dioxide. The electrons, passed along electron-carrier molecules, then go through the oxidative phosphorylation and terminal oxidation processes. Also called the Krebs cycle or tricarboxylic acid cycle."}]},{"chapter":7,"cards":[{"front":"photosystem","back":"A discrete unit of organization of chlorophyll and other pigment molecules embedded in the thylakoids of chloroplasts and involved in the light-dependent reactions of photosynthesis."},{"front":"Rubisco","back":"RuBP carboxylase/oxygenase, the enzyme that catalyzes the initial reaction of the Calvin cycle, involving the fixation of carbon dioxide to ribulose 1,5-bisphosphate (RuBP)."},{"front":"Calvin cycle","back":"The series of enzymatically mediated photosynthetic reactions during which CO is reduced to glyceraldehyde 3-phosphate 2 (3-phosphoglyceraldehyde) and the CO acceptor, ribulose 1,5-bisphosphate, 2 is regenerated. For every three molecules of CO entering the cycle, a net 2 gain of one molecule of glyceraldehyde 3-phosphate results."},{"front":"photorespiration","back":"The oxygenase activity of Rubisco combined with the salvage pathway, consuming O and releasing CO ; occurs when Rubisco 2 2 binds O instead of CO . 2 2 photosynthesis [Gk. photos, light, + syn, together + tithenai, to place]: Conversion of light energy to chemical energy; the production of carbohydrates from carbon dioxide and water in the presence of chlorophyll by using light energy."},{"front":"carbon fixation","back":"The conversion of CO into organic compounds during 2 photosynthesis."},{"front":"carotenoids","back":"A class of fat-soluble pigments that includes the carotenes (yellow and orange pigments) and the xanthophylls (yellow pigments); found in chloroplasts and chromoplasts of plants. Carotenoids act as accessory pigments in photosynthesis."},{"front":"leaf","back":"The principal lateral appendage of the stem; highly variable in both structure and function; the foliage leaf is specialized as a photosynthetic organ."},{"front":"reaction center","back":"The complex of proteins and chlorophyll molecules of a photosystem, capable of converting light energy to chemical energy in the photochemical reaction."},{"front":"crassulacean acid metabolism (CAM)","back":"A variant of the C pathway; the 4 enzyme PEP (phosphoenolpyruvate) carboxylase fixes CO into C 2 4 compounds at night, then during the daytime, the fixed CO is transferred to 2 the ribulose bisphosphate of the Calvin cycle in the same cell; characteristic of most succulent plants, such as cacti."}]},{"chapter":8,"cards":[{"front":"gametic meiosis","back":"Meiosis resulting in the formation of haploid gametes from a diploid individual; the gametes fuse to form a diploid zygote that divides to form another diploid individual."},{"front":"homeotic mutation","back":"A mutation that changes organ identity so that the wrong structures appear in the wrong place or at the wrong time."},{"front":"homologous chromosomes","back":"Chromosomes that associate in pairs in the first stage of meiosis; each member of the pair is derived from a different parent. Also called homologs."},{"front":"mutation","back":"Any change in the hereditary state of an organism; such changes may occur at the level of the gene (gene mutations, or point mutations) or at the level of the chromosome (chromosome mutations)."},{"front":"zygotic meiosis","back":"Meiosis in a zygote to form four haploid cells, which divide by mitosis to produce either more haploid cells or a multicellular individual that eventually gives rise to gametes."},{"front":"gamete","back":"A haploid reproductive cell; gametes fuse in pairs to form zygotes, which are diploid."},{"front":"genotype","back":"The genetic constitution, latent or expressed, of an organism, in contrast to the phenotype; the sum total of all the genes present in an individual."},{"front":"heredity","back":"The transmission of characteristics from parent to offspring through the gametes."},{"front":"linkage","back":"The tendency for certain genes to be inherited together because they are located on the same chromosome."},{"front":"phenotype","back":"The physical appearance of an organism; results from the interaction between the genetic constitution (genotype) of the organism and its environment."},{"front":"zygote","back":"The diploid (2n) cell resulting from the fusion of male and female gametes."},{"front":"Mendel’s second law","back":"States that the inheritance of one pair of characteristics is independent of the simultaneous inheritance of other traits; such characteristics are assorted independently, as though there were no others present (later modified by the discovery of linkage)."},{"front":"pairing of chromosomes","back":"Side-by-side association of homologous chromosomes."}]},{"chapter":9,"cards":[{"front":"cDNA","back":"A single-stranded molecule of DNA synthesized from an mRNA template by reverse transcription."},{"front":"cisterna","back":"A flattened or saclike portion of the endoplasmic reticulum or a Golgi body (dictyosome)."},{"front":"complementary DNA","back":"A single-stranded molecule of DNA synthesized from an mRNA template by reverse transcription."},{"front":"DNA sequencing","back":"Determination of the order of nucleotides in a DNA molecule."},{"front":"genetic recombination","back":"The occurrence of gene combinations in progeny that are different from the combinations present in their parents."},{"front":"messenger RNA","back":"The class of RNA that carries genetic information from the gene to the ribosomes, where it is translated into protein."},{"front":"mRNA","back":"The class of RNA that carries genetic information from the gene to the ribosomes, where it is translated into protein."},{"front":"multigene family","back":"A collection of related genes on a chromosome; most eukaryotic genes appear to be members of multigene families."},{"front":"noncoding RNA","back":"An RNA molecule that is not translated into protein."},{"front":"regulator gene","back":"A gene that prevents or represses the activity of the structural genes in an operon."},{"front":"ribosomal RNA","back":"Any of a number of specific molecules that form part of the structure of a ribosome and participate in the synthesis of proteins."},{"front":"satellite DNA","back":"A short nucleotide sequence repeated in tandem fashion many thousands of times; this region of the chromosome has a distinctive base composition and is not transcribed."},{"front":"transfer RNA","back":"Low-molecular-weight RNA that becomes attached to an amino acid and guides it to the correct position on the ribosome for protein synthesis; there is at least one tRNA molecule for each amino acid."},{"front":"tRNA","back":"Low-molecular-weight RNA that becomes attached to an amino acid and guides it to the correct position on the ribosome for protein synthesis; there is at least one tRNA molecule for each amino acid."},{"front":"deoxyribonucleic acid (DNA)","back":"Carrier of genetic information in cells; composed of chains of phosphate, sugar molecules (deoxyribose), and Glossary G–7 purines and pyrimidines; capable of self-replication and determines RNA synthesis."},{"front":"rRNA","back":"See ribosomal RNA. Glossary G–21"},{"front":"alternation of generations","back":"A reproductive cycle in which a haploid (n) phase, the gametophyte, produces gametes, which fuse in pairs to form a zygote, which then germinates to produce a diploid (2n) phase, the sporophyte. Spores produced by meiotic division in the sporophyte give rise to new gametophytes, completing the cycle. amino acids [Gk. Ammon, referring to the Egyptian sun god, near whose"},{"front":"allele","back":"One of the two or more alternative forms of a gene. G–2 Glossary"},{"front":"anticodon","back":"In a tRNA molecule, the three-nucleotide sequence that base-pairs with the mRNA codon for the amino acid carried by that particular tRNA; the anticodon is complementary to the mRNA codon."},{"front":"chromatin","back":"The deeply staining complex of DNA and proteins that forms eukaryotic chromosomes."}]},{"chapter":10,"cards":[{"front":"cloning","back":"Producing a cell line or culture, all of whose members are characterized by a specific DNA sequence; a key element in genetic engineering."},{"front":"gene transfer","back":"The transfer of naked DNA from one organism to another; transposons are often used as vectors in transformation when carried out in the laboratory. Also called gene transfer."},{"front":"genetic engineering","back":"The manipulation of genetic material for practical purposes. Also called recombinant DNA technology."},{"front":"genome","back":"The totality of genetic information contained in the nucleus, plastid, or mitochondrion."},{"front":"genomics","back":"The field of genetics that studies the content, organization, and function of genetic information in whole genomes."},{"front":"restriction enzymes","back":"Enzymes that cleave the DNA double helix at specific nucleotide sequences."},{"front":"tissue culture","back":"A technique for maintaining fragments of plant or animal tissue alive in a medium after removal from the organism."},{"front":"totipotent","back":"For a plant cell, having the potential to develop into an entire plant."},{"front":"transformation","back":"The transfer of naked DNA from one organism to another; transposons are often used as vectors in transformation when carried out in the laboratory. Also called gene transfer."},{"front":"transgenic organism","back":"An organism whose genome contains DNA, from the same or a different species, that has been modified by the methods of genetic engineering."},{"front":"polymerase chain reaction (PCR)","back":"A technique for amplifying specific regions of DNA by multiple cycles of DNA polymerization, utilizing special primers, DNA polymerase molecules, and nucleotides; each cycle is followed by a brief heat treatment to separate complementary strands."}]},{"chapter":11,"cards":[{"front":"allopatric speciation","back":"Speciation that occurs as the result of the geographic separation of a population of organisms."},{"front":"convergent evolution","back":"The independent development of similar structures in organisms that are not directly related; often found in organisms living in similar environments."},{"front":"evolution","back":"The derivation of progressively better-adapted forms of life from simple ancestors; Darwin proposed that natural selection is the principal mechanism by which evolution takes place."},{"front":"gene flow","back":"The movement of alleles into and out of a population."},{"front":"gene pool","back":"All the alleles of all the genes of all the individuals in a population."},{"front":"genetic drift","back":"Evolution (change in allele frequencies) owing to chance processes."},{"front":"macroevolution","back":"Evolutionary change on a grand scale, involving major evolutionary trends."},{"front":"microevolution","back":"Evolutionary change within a population over a succession of generations."},{"front":"natural selection","back":"The differential reproduction of genotypes based on their genetic constitution."},{"front":"parallel evolution","back":"The development of similar structures having similar functions in two or more evolutionary lines as a result of the same kind of selective pressures."},{"front":"speciation","back":"The origin of new species in evolution."},{"front":"adaptive radiation","back":"The evolution from one kind of organism to several divergent forms, each specialized to fit a distinct and diverse way of life."},{"front":"fitness","back":"The genetic contribution of an organism to future generations, relative to the contributions of other organisms living in the same environment that have different genotypes."},{"front":"gene frequency","back":"The relative occurrence of a particular allele in a population. Also called allele frequency."},{"front":"Hardy-Weinberg law","back":"The mathematical expression of the relationship between the relative frequencies of two or more alleles in a population. It demonstrates that the frequencies of alleles and genotypes will remain constant in a random-mating population in the absence of inbreeding, selection, or other evolutionary forces."}]},{"chapter":12,"cards":[{"front":"systematics","back":"Scientific study of the kinds and diversity of organisms and of the relationships between them."},{"front":"clade","back":"A monophyletic group, made up of an ancestor and all of its descendants."},{"front":"cladogram","back":"A line diagram that branches repeatedly and suggests phylogenetic relationships among organisms."},{"front":"homology","back":"A condition indicative of the same phylogenetic, or evolutionary, origin, but not necessarily the same in present structure and/or function."},{"front":"phylogeny","back":"Evolutionary relationships among organisms; the developmental history of a group of organisms."},{"front":"synapomorphies","back":"Character states (two or more forms of a character) that arose in the common ancestor of a group and are present in all of its members."},{"front":"taxon","back":"General term for any one of the taxonomic categories, such as species, class, order, or phylum."},{"front":"taxonomy","back":"The science of the classification of organisms."}]},{"chapter":13,"cards":[{"front":"Bacteria","back":"The phylogenetic domain consisting of all prokaryotes that are not members of the domain Archaea."},{"front":"lysogenic bacteria","back":"Bacteria-carrying viruses (phages) that eventually break loose from the bacterial chromosome and set up an active cycle of infection, producing lysis of their bacterial hosts."},{"front":"bacteriophage","back":"A virus that parasitizes bacterial cells."},{"front":"Archaea","back":"A phylogenetic domain of prokaryotes consisting of the methanogens, most extreme halophiles and hyperthermophiles, and Thermoplasma."},{"front":"plasmid","back":"A relatively small fragment of DNA that can exist free in the cytoplasm of a bacterium and can be integrated into and then replicated with a chromosome. Plasmids make up about 5 percent of the DNA of many bacteria, but are rare in eukaryotes."},{"front":"prokaryote","back":"A cell lacking a membrane- bounded nucleus and membrane-bounded organlles; Bacteria and Archaea."},{"front":"Ti plasmid","back":"A circular plasmid of Agrobacterium tumifaciens that enables the bacterium to infect plant cells and produce a tumor (crown gall tumor); a powerful tool in biotechnology in the transfer of foreign genes into plant genomes."},{"front":"ribonucleic acid (RNA)","back":"Type of nucleic acid formed on chromosomal DNA and involved in protein synthesis; composed of chains of phosphate, sugar molecules (ribose), and purines and pyrimidines. RNA is the genetic material of many kinds of viruses."},{"front":"capsid","back":"The protein coat of a virus particle."},{"front":"chromosome","back":"The structure that carries the genes. Eukaryotic chromosomes are visualized as threads or rods of chromatin, appearing in contracted form during mitosis and meiosis, and otherwise are enclosed in a nucleus; each eukaryotic chromosome contains a linear DNA molecule. Prokaryotes typically have a single chromosome consisting of a circular DNA molecule."}]},{"chapter":14,"cards":[{"front":"ascogenous hyphae","back":"Hyphae containing paired haploid male and female nuclei; they develop from an ascogonium and eventually give rise to asci."},{"front":"ascospore","back":"A spore produced within an ascus; found in ascomycetes."},{"front":"basidiospore","back":"A spore of the Basidiomycota, produced within and borne on a basidium following nuclear fusion and meiosis. Also called a basidiocarp."},{"front":"conidium","back":"An asexual fungal spore not contained within a sporangium; may be produced singly or in chains; most conidia are multinucleate."},{"front":"dikaryon","back":"In fungi, a mycelium with paired nuclei, each usually derived from a different parent."},{"front":"dikaryotic","back":"In fungi, having pairs of nuclei within cells or compartments."},{"front":"yeast","back":"A unicellular fungus that reproduces primarily by budding; not a taxonomic group but merely a morphological growth form; encompasses zygomycetes, ascomycetes, and basidiomycetes."}]},{"chapter":15,"cards":[{"front":"alga","back":"Traditional term for a series of unrelated groups of photosynthetic eukaryotic organisms lacking multicellular sex organs (except for the charophytes); the misnamed “blue-green algae” are cyanobacteria, one of the groups of photosynthetic bacteria."},{"front":"chlorophyll","back":"The green pigment of plant cells; the receptor of light energy in photosynthesis; also found in algae and photosynthetic bacteria."},{"front":"phytoplankton","back":"Aquatic, free- floating, microscopic, photosynthetic organisms."},{"front":"protists","back":"All organisms that do not have the distinct characteristics of fungi, animals, or plants."},{"front":"stramenopiles","back":"Organisms with one long, ornamented (tinsel) flagellum and one shorter, smooth (whiplash) flagellum; include oomycetes, chrysophytes, diatoms, brown algae, and certain other groups. Also called stramenopiles."}]},{"chapter":16,"cards":[{"front":"bryophytes","back":"Members of the phyla of nonvascular plants; the mosses, hornworts, and liverworts."},{"front":"antheridiophore","back":"In some liverworts, a stalk that bears antheridia."},{"front":"archegoniophore","back":"In some liverworts, a stalk that bears archegonia."},{"front":"archegonium","back":"A multicellular structure in which a single egg is produced; found in the bryophytes and some vascular plants."},{"front":"calyptra","back":"The hood or cap that partly or entirely covers the capsule of some species of mosses; formed from the expanded archegonial wall."},{"front":"gametophore","back":"In bryophytes, a fertile stalk that bears gametangia."},{"front":"peristome","back":"In mosses, a fringe of teeth around the opening of the sporangium."},{"front":"protonema","back":"The first stage in development of the gametophyte of mosses and certain liverworts; protonemata may be filamentous or platelike."},{"front":"rhizoids","back":"(1) Branched rootlike extensions of fungi and algae that absorb water, food, and nutrients; (2) root-hair-like structures in liverworts, mosses, and some vascular plants, occurring on free-living gametophytes."}]},{"chapter":17,"cards":[{"front":"circinate vernation","back":"In ferns, the coiled arrangement of leaves and leaflets in the bud; such an arrangement uncoils gradually as the leaf develops."},{"front":"heterosporous","back":"Having two kinds of spores, designated as microspores and megaspores."},{"front":"microphyll","back":"A small leaf with one vein and one leaf trace, not associated with either a leaf gap or a leaf trace gap; in contrast to a megaphyll. Microphylls are characteristic of the lycophytes."},{"front":"homosporous","back":"Having only one kind of spore."}]},{"chapter":18,"cards":[{"front":"pollen grain","back":"In seed plants, a microspore containing a mature or immature microgametophyte (male gametophyte)."},{"front":"sporopollenin","back":"The tough substance of which the exine, or outer wall, of spores and pollen grains is composed; a cyclic alcohol highly resistant to decay."},{"front":"pollen mother cell","back":"A cell in which meiosis will occur, resulting in four microspores; in seed plants, often called a pollen mother cell. Also called a microsporocyte or pollen mother cell."},{"front":"pollen","back":"A collective term for pollen grains."}]},{"chapter":19,"cards":[{"front":"accessory fruit","back":"A fruit, or assemblage of fruits, with fleshy parts derived largely or entirely from tissues other than the ovary. An example is the strawberry, with a fleshy receptacle and fruits (achenes) embedded in its surface."},{"front":"aggregate fruit","back":"A fruit developing from the several separate carpels of a single flower."},{"front":"bisexual flower","back":"A flower that has at least one functional stamen and one functional carpel."},{"front":"complete flower","back":"A flower having four whorls of floral parts—sepals, petals, stamens, and carpels."},{"front":"flower","back":"The reproductive structure of angiosperms; a complete flower includes calyx, corolla, androecium (stamens), and gynoecium (carpels); all flowers contain at least one stamen or one carpel."},{"front":"incomplete flower","back":"A flower lacking one or more of the four kinds of floral parts, that is, lacking sepals, petals, stamens, or carpels."},{"front":"irregular flower","back":"A flower in which one or more members of at least one whorl differ in form from other members of the same whorl."},{"front":"multiple fruit","back":"A cluster of mature ovaries produced by a cluster of flowers, as in the pineapple."},{"front":"nonclimacteric fruits","back":"Fruits such as citrus fruits, grapes, and strawberries that do not exhibit the large increase in cellular respiration during ripening that is seen in climacteric fruits."},{"front":"ovule","back":"A structure in seed plants containing the female gametophyte with egg cell, all surrounded by the nucellus and one or two integuments; when mature, an ovule becomes a seed."},{"front":"perfect flower","back":"A flower having both stamens and carpels; hermaphroditic flower."},{"front":"simple fruit","back":"A fruit derived from one carpel or several united carpels."},{"front":"fruit","back":"In angiosperms, a mature, ripened ovary (or group of ovaries) containing the seeds, together with any adjacent parts that may be fused with it at maturity; sometimes the term is applied informally, and misleadingly, as in “fruiting body,” to the reproductive structures of other kinds of organisms."},{"front":"imperfect flower","back":"A flower lacking either stamens or carpels."},{"front":"acropetal development","back":"Development (or differentiation) that proceeds toward the apex of an organ; the opposite of basipetal development (or differentiation)."},{"front":"adnate","back":"Describing fused unlike parts, such as stamens and petals."},{"front":"androecium","back":"(1) The floral whorl that comprises the stamens; (2) in leafy liverworts, a packetlike swelling containing the antheridia."},{"front":"angiosperm","back":"Literally, a seed borne in a vessel (carpel); thus, one of a group of plants whose seeds are borne within a mature ovary (fruit)."},{"front":"antheridium","back":"A sperm-producing structure that may be multicellular or unicellular."},{"front":"basipetal development","back":"Development (or differentiation) that proceeds toward the base (away from the apex) of an organ; the opposite of acropetal development (or differentiation)."}]},{"chapter":20,"cards":[{"front":"coevolution","back":"The simultaneous evolution of adaptations in two or more populations interacting so closely that each is a strong selective force on the other."},{"front":"generative cell","back":"(1) In many gymnosperms, the cell of the male gametophyte that divides to form the sterile and spermatogenous cells; (2) in angiosperms, the cell of the male gametophyte that divides to form two sperm."},{"front":"magnoliids","back":"A clade, or evolutionary line, of angiosperms leading to the eudicots. The leaves of most magnoliids possess ether-containing oil cells."}]},{"chapter":21,"cards":[{"front":"artificial selection","back":"The breeding of selected organisms to produce strains with desired characteristics."}]},{"chapter":22,"cards":[{"front":"embryo","back":"In plants, a young sporophyte before the start of a period of rapid growth (germination in seed plants)."},{"front":"embryo sac","back":"The female gametophyte of angiosperms, generally an eight- nucleate, seven-celled structure; the seven cells are the egg cell, two synergids, and three antipodals (each with a single nucleus), and the central cell (with two nuclei)."},{"front":"embryogenesis","back":"Development of an embryo from a fertilized egg, or zygote. Also called embryogeny."},{"front":"embryophytes","back":"The bryophytes and vascular plants, both of which produce embryos; a synonym for plants."},{"front":"polyembryony","back":"Having more than one embryo within the developing seed."},{"front":"proembryo","back":"An embryo in early stages of development, before the embryo proper and suspensor become distinct."},{"front":"seed coat","back":"The outer layer of the seed, developed from the integuments of the ovule."},{"front":"seedling","back":"A young sporophyte, which develops from a germinating seed. G–22 Glossary"},{"front":"cotyledon","back":"Seed leaf; generally absorbs food in monocotyledons and stores food in other angiosperms."},{"front":"epicotyl","back":"The upper portion of the axis of an embryo or seedling, above the point of insertion of the cotyledons (seed leaves) and below the next leaf or leaves."},{"front":"germination","back":"The beginning or resumption of growth by a spore, seed, bud, or other structure."},{"front":"hypocotyl","back":"The portion of an embryo or seedling situated between the point of attachment of the cotyledons and the radicle."},{"front":"monocotyledons","back":"One of the two great classes of angiosperms, Monocotyledonae; plants having an embryo with one cotyledon; abbreviated as “monocots.”"},{"front":"plumule","back":"The first bud of an embryo; the portion of the young shoot above the cotyledons."},{"front":"pollen tube","back":"A tube formed after germination of the pollen grain; carries the male gametes into the ovule."},{"front":"suspensor","back":"A structure at the base of the embryo in many vascular plants. In some plants, it pushes the embryo into nutrient-rich tissue of the female gametophyte."},{"front":"dicotyledons","back":"Obsolete term used to refer to all angiosperms other than monocotyledons; characterized by having two cotyledons."},{"front":"eudicotyledons","back":"One of two major classes of angiosperms, Eudicotyledonae; formerly grouped with the magnoliids, a diverse group of archaic flowering plants, as “dicots”; plants with an embryo having two cotyledons; abbreviated as “eudicot.”"}]},{"chapter":23,"cards":[{"front":"apical meristem","back":"The meristem at the tip of the root or shoot in a vascular plant."},{"front":"collenchyma","back":"A supporting tissue composed of collenchyma cells; common in regions of primary growth in stems and in some leaves."},{"front":"collenchyma cell","back":"Elongated living cell with unevenly thickened, nonlignified primary cell wall."},{"front":"ground meristem","back":"The primary meristem, or meristematic tissue, that gives rise to the ground tissues."},{"front":"meristem","back":"Embryonic tissue regions, primarily concerned with formation of new cells."},{"front":"palisade parenchyma","back":"A leaf tissue composed of columnar chloroplast-bearing parenchyma cells with their long axes at right angles to the leaf surface."},{"front":"parenchyma cell","back":"Living, generally thin-walled plant cell of variable size and form; the most abundant kind of cell in plants."},{"front":"promeristem","back":"The initiating cells (initials) and their most recent derivatives in an apical meristem; the least differentiated, or determined, part of an apical meristem."},{"front":"protophloem","back":"The first-formed elements of the phloem in a plant organ; first part of the primary phloem."},{"front":"protoxylem","back":"The first part of the primary xylem, which matures during elongation of the plant part in which it is found."},{"front":"sclerenchyma cells","back":"Cells of variable form and size with more or less thick, often lignified, secondary walls; may or may not be living at maturity; include fibers and sclereids."},{"front":"tissue system","back":"In plants, a tissue or group of tissues organized into a structural and functional unit in the plant or plant organ. There are three tissue"},{"front":"parenchyma","back":"A tissue composed of parenchyma cells."},{"front":"spongy parenchyma","back":"A leaf tissue composed of loosely arranged, chloroplast- bearing cells. sporangiophore (spo • r a ̆nj ı̆ • o • fōr) [Gk. spora, seed, + pherein, to carry]: A branch bearing one or more sporangia. sporangium, pl. sporangia (spo • r ănjı̆ • ŭm) [Gk. spora, seed, + angeion,"},{"front":"companion cell","back":"A specialized parenchyma cell associated with a sieve-tube element in angiosperm phloem and arising from the same mother cell as the sieve-tube element."},{"front":"epidermis","back":"The outermost layer of cells of the leaf and young stems and roots; primary in origin."},{"front":"fiber","back":"An elongated, tapering, generally thick-walled sclerenchyma cell of vascular plants; its walls may or may not be lignified; it may or may not have a living protoplast at maturity."},{"front":"hypocotyl-root axis","back":"The embryo axis below the point of attachment of the cotyledon or cotyledons, consisting of the hypocotyl and the apical meristem of the root or radicle."},{"front":"leaf gap","back":"In ferns, region of parenchyma tissue in the primary vascular cylinder above the point of departure of the leaf trace or traces."},{"front":"metaphloem","back":"Part of the primary phloem that differentiates after the protophloem and before the secondary phloem, if any secondary phloem is formed in a given taxon."}]},{"chapter":24,"cards":[{"front":"branch root","back":"A root that arises from another, older root. Also called a branch root or a secondary root, if the older root is the primary root."},{"front":"lateral root","back":"A root that arises from another, older root. Also called a branch root or a secondary root, if the older root is the primary root."},{"front":"root hairs","back":"Tubular outgrowths of epidermal cells of the root; greatly increase the absorbing surface of the root."},{"front":"secondary root","back":"A root that arises from another, older root. Also called a branch root or a secondary root, if the older root is the primary root."},{"front":"taproot","back":"The primary root of a plant, formed in direct continuation with the root tip or radicle of the embryo; forms a stout, tapering main root from which arise smaller, lateral roots."},{"front":"Casparian strip","back":"A bandlike region of primary wall containing suberin and lignin; found in anticlinal—radial and transverse—walls of endodermal and exodermal cells."},{"front":"pericycle","back":"A tissue characteristic of roots that is bounded externally by the endodermis and internally by the phloem."},{"front":"primary root","back":"The first root of the plant, developing as a continuation of the root tip or radicle of the embryo; the taproot."},{"front":"rootcap","back":"A thimblelike mass of cells that covers and protects the growing tip of a root. It typically consists of a central column of cells, the columella, and a lateral portion, the lateral rootcap, which surrounds the columella."},{"front":"endodermis","back":"A single layer of cells forming a sheath around the vascular region in roots and some stems; endodermal cells are characterized by a Casparian strip within radial and transverse walls. In roots and stems of seed plants, the endodermis is the innermost layer of the cortex."}]},{"chapter":25,"cards":[{"front":"alternate phyllotaxy","back":"Leaf arrangement in which there is one bud or one leaf at a node."},{"front":"guard cells","back":"Pairs of specialized epidermal cells surrounding a pore, or stoma; changes in the turgor of a pair of guard cells cause opening and closing of the pore."},{"front":"leaf primordium","back":"A lateral outgrowth from the apical meristem that will eventually become a leaf."},{"front":"stoma","back":"A minute opening, bordered by guard cells, in the epidermis of leaves and stems through which gases"},{"front":"abscission","back":"The dropping off of leaves, flowers, fruits, or other plant parts, usually following the formation of an abscission zone."},{"front":"abscission zone","back":"The area at the base of a leaf, flower, fruit, or other plant part containing tissues that play a role in the separation of the plant part from the plant body."},{"front":"blade","back":"The broad, expanded part of a leaf; the lamina."},{"front":"compound leaf","back":"A leaf with a blade divided into several distinct leaflets."},{"front":"disk flowers","back":"The actinomorphic, tubular flowers of the Asteraceae; in contrast to flattened, zygomorphic ray flowers. In many Asteraceae, the disk flowers occur in the center of the inflorescence, the ray flowers around the margins."},{"front":"helical phyllotaxis","back":"Leaf arrangement in which there is one leaf at a node, forming a helical pattern around the stem. Also called alternate phyllotaxis."},{"front":"inflorescence","back":"A flower cluster, with a definite arrangement of flowers."},{"front":"internode","back":"The region of a stem between two successive nodes."},{"front":"leaf buttress","back":"A lateral protrusion below the apical meristem; represents the initial stage in the development of a leaf primordium."},{"front":"mesophyll","back":"The ground tissue (parenchyma) of a leaf, located between the layers of epidermis; mesophyll cells generally contain chloroplasts."},{"front":"netted venation","back":"The arrangement of veins in the leaf blade that resembles a net; characteristic of the leaves of all angiosperms except for monocots. Also called reticulate venation. G–16 Glossary"},{"front":"node","back":"The part of a stem where one or more leaves are attached."},{"front":"opposite phyllotaxis","back":"Leaf arrangement in which leaves occur in pairs at a node."},{"front":"parallel venation","back":"The pattern of venation in which the principal veins of the leaf are parallel or nearly so; characteristic of monocots."},{"front":"phyllotaxis","back":"The arrangement of leaves on a stem. Also called phyllotaxy."},{"front":"ray flowers","back":"In Asteraceae, the flattened, zygomorphic flowers; in contrast to the actinomorphic, tubular disk flowers. In many Asteraceae, the ray flowers occur around the margins of the inflorescence, the disk flowers in the center."}]},{"chapter":26,"cards":[{"front":"annual ring","back":"In wood, the growth layer formed during a single year."},{"front":"cork cambium","back":"The lateral meristem that forms the periderm, producing cork (phellem) toward the surface (outside) of the plant and phelloderm toward the inside; common in stems and roots of gymnosperms and woody angiosperms. Also called phellogen."},{"front":"vascular cambium","back":"A cylindrical sheath of meristematic cells that divides to produce secondary phloem and secondary xylem."},{"front":"cambium","back":"A meristem that gives rise to parallel rows of cells; a term commonly applied to the vascular cambium and the cork cambium, or phellogen."},{"front":"compression wood","back":"The reaction wood of conifers; develops on the lower sides of leaning trunks or limbs."},{"front":"conducting phloem","back":"The part of the inner bark that contains living, functional sieve elements and is actively engaged in the transport of food substances."},{"front":"diffuse-porous wood","back":"A wood in which the pores, or vessels, are fairly uniformly distributed throughout the growth layers or in which the size of pores changes only slightly from early wood to late wood."},{"front":"early wood","back":"The first-formed wood of a growth increment; contains larger cells and is less dense than the subsequently formed late wood; replaces the term “spring wood.”"},{"front":"fascicular cambium","back":"The vascular cambium originating within a vascular bundle, or fascicle."},{"front":"growth ring","back":"A growth layer in the secondary xylem or secondary phloem, as seen in transverse section; may be called a growth increment, especially where seen in other than transverse section."},{"front":"hardwood","back":"A name commonly applied to the wood of a magnoliid or eudicot tree."},{"front":"heartwood","back":"Nonliving and commonly dark-colored wood in which no water transport occurs; it is surrounded by sapwood. Glossary G–11"},{"front":"inner bark","back":"In older trees, the living part of the bark; the bark inside the innermost periderm."},{"front":"interfascicular cambium","back":"The vascular cambium arising between the fascicles, or vascular bundles, from interfascicular parenchyma."},{"front":"late wood","back":"The last part of the growth increment formed in the growing season; it contains smaller cells and is denser than the early wood; replaces the term “summer wood.”"},{"front":"lateral meristems","back":"Meristems that give rise to secondary tissue; the vascular cambium and cork cambium."},{"front":"nonconducting phloem","back":"The part of the inner bark in which the sieve elements are dead. The phloem parenchyma cells and ray parenchyma cells of nonconducting phloem may remain alive and continue to function as storage cells for many years."},{"front":"outer bark","back":"In older trees, the dead part of the bark; the innermost periderm and all tissues outside it. Also called rhytidome."},{"front":"periderm","back":"Outer protective tissue that replaces epidermis when it is destroyed during secondary growth; includes cork, cork cambium, and phelloderm."},{"front":"radial system","back":"In secondary xylem and secondary phloem, includes all the rays, the cells of which are derived from ray initials. Also called the horizontal system or ray system."}]},{"chapter":27,"cards":[{"front":"abscisic acid","back":"A plant hormone that brings about dormancy in buds, maintains dormancy in seeds, and brings about stomatal closing, among other effects."},{"front":"auxins","back":"A class of plant hormones that control cell elongation, among other effects."},{"front":"cytokinin","back":"A class of plant hormones that promotes cell division, among other effects."},{"front":"ethylene","back":"A simple hydrocarbon, H C CH ; a plant hormone involved in the 2 2 ripening of fruit."},{"front":"gibberellic acid","back":"The main gibberellin found in fungal cultures; occurs rarely in plants, but is commonly used in the malting of barley and the management of fruit crops."},{"front":"gibberellins","back":"A class of plant hormones, the best known effect of which is to increase the elongation of plant stems."},{"front":"apical dominance","back":"The influence exerted by a terminal bud in suppressing the growth of lateral, or axillary, buds."},{"front":"indole-3-acetic acid (IAA)","back":"A naturally occurring auxin; a plant hormone."},{"front":"brassinosteroids","back":"A group of growth-promoting steroid hormones in plants that play essential roles in a wide range of developmental processes, such as cell division and cell elongation in roots and stems, vascular differentiation, responses to light (photomorphogenesis), flower and fruit development, resistance to stresses, and senescence."}]},{"chapter":28,"cards":[{"front":"geotropism","back":"The response of a shoot or root to the pull of the Earth’s gravity. Also called geotropism."},{"front":"gravitropism","back":"The response of a shoot or root to the pull of the Earth’s gravity. Also called geotropism."},{"front":"heliotropism","back":"The ability of the leaves and flowers of many plants to move diurnally, orienting themselves either perpendicular to or parallel to the sun’s direct rays. Also called heliotropism."},{"front":"hydrotropism","back":"The directed growth of plant roots in response to a moisture gradient."},{"front":"photoperiodism","back":"Response of organisms to duration and timing of day and night; a mechanism that has evolved for measuring seasonal time. photophosphorylation [Gk. photos, light, + phosphoros, bringing light]: Formation of ATP in the chloroplast during photosynthesis."},{"front":"thigmomorphogenesis","back":"The alteration of plant growth patterns in response to mechanical stimuli."},{"front":"tropism","back":"A movement response to an external stimulus in which the direction of movement is usually determined by the direction from which the most intense stimulus comes."},{"front":"vernalization","back":"The induction of flowering by cold treatment."},{"front":"phytochrome","back":"A phycobilinlike pigment, found in the cytoplasm of plants and a few green algae, that is associated with the absorption of light; photoreceptor for red and far-red light; involved in a number of timing processes, such as flowering, dormancy, leaf formation, and seed germination."},{"front":"thigmotropism","back":"A response to contact with a solid object."},{"front":"circadian rhythms","back":"Regular rhythms of growth and activity that occur in an approximately 24-hour cycle."},{"front":"etiolation","back":"A condition involving increased stem elongation, poor leaf development, and lack of chlorophyll; found in plants growing in the dark or with a greatly reduced amount of light."},{"front":"nastic movement","back":"A plant movement that occurs in response to a stimulus, but in a direction independent of the direction of the stimulus."},{"front":"solar tracking","back":"The ability of the leaves and flowers of many plants to move diurnally, orienting themselves either perpendicular to or parallel to the sun’s direct rays. Also called heliotropism."},{"front":"dormancy","back":"A special condition of arrested growth in which the plant and such plant parts as buds and seeds do not begin to grow without special environmental cues. The requirement for such cues, which G–8 Glossary include cold exposure and a suitable photoperiod, prevents the breaking of dormancy during superficially favorable growing conditions."}]},{"chapter":29,"cards":[{"front":"arbuscular mycorrhizas","back":"Mycorrhizas in which the fungal hyphae penetrate the cortical cells of the plant root, where they form branched structures, the arbuscules. Also called endomycorrhizas."},{"front":"endomycorrhizas","back":"Mycorrhizas in which the fungal hyphae penetrate the cortical cells of the plant root, where they form branched structures, the arbuscules. Also called endomycorrhizas."},{"front":"loam soils","back":"Soils containing sand, silt, and clay in proportions that result in ideal agricultural soils."},{"front":"mycorrhizas","back":"Literally meaning “fungus roots”; intimate and mutually beneficial symbiotic associations between fungi and roots; characteristic of most vascular plants."},{"front":"nitrogen fixation","back":"The incorporation of atmospheric nitrogen into nitrogen compounds; carried out by certain free-living and symbiotic bacteria."},{"front":"ectomycorrhizas","back":"Mycorrhizas in which the fungus does not penetrate living cells in the roots. The hyphae grow between the cells of the root epidermis and cortex, forming a highly branched network called the Hartig net. The hyphae also form a mantle, or sheath, that covers the root surface."},{"front":"bacteroid","back":"An enlarged, deformed Rhizobium or Bradyrhizobium cell found in root nodules; capable of nitrogen fixation."},{"front":"biome","back":"A complex of terrestrial communities of very wide extent, characterized by its climate and soil; the largest ecological unit."},{"front":"cation exchange","back":"The replacement of mineral cations weakly bound to the surface of soil particles by other cations."},{"front":"essential elements","back":"Chemical elements essential for normal plant growth and development. Also called essential minerals and essential inorganic nutrients."},{"front":"fine roots","back":"Roots actively engaged in the uptake of water and minerals from the upper 15 centimeters of soil. Also called feeder roots."},{"front":"macronutrients","back":"Inorganic chemical elements required in large amounts for plant growth, such as nitrogen, potassium, calcium, phosphorus, magnesium, and sulfur."},{"front":"micronutrients","back":"Inorganic chemical elements required only in very small, or trace, amounts for plant growth, such as iron, chlorine, copper, manganese, zinc, molybdenum, nickel, and boron."},{"front":"nitrogen-fixing bacteria","back":"Soil bacteria that convert atmospheric nitrogen into nitrogen compounds."},{"front":"nodules","back":"Enlargements or swellings on the roots of legumes and certain other plants inhabited by symbiotic nitrogen-fixing bacteria."},{"front":"prop roots","back":"Adventitious roots arising from the stem above soil level and helping to support the plant; common in many monocots, such as maize (Zea mays)."},{"front":"rhizobia","back":"Bacteria of the genera Rhizobium or Bradyrhizobium, which may be involved in a symbiotic relationship with leguminous plants that results in nitrogen fixation."}]},{"chapter":30,"cards":[{"front":"transpiration","back":"The loss of water vapor by plant parts; most transpiration occurs through stomata."},{"front":"transpiration stream","back":"The flow of water through the xylem, from the roots to the leaves."},{"front":"water potential","back":"The algebraic sum of the solute potential and the pressure potential, or wall pressure; the potential energy of water."},{"front":"guttation","back":"The exudation of liquid water from leaves; caused by root pressure."},{"front":"osmosis","back":"The diffusion of water, or any solvent, across a selectively permeable membrane; in the absence of other forces, the movement of water during osmosis is always from a region of greater water potential to one of lesser water potential."},{"front":"phloem unloading","back":"The process by which sugars and other assimilates transported in the phloem exit the sieve tubes of sink tissues."},{"front":"phototropism","back":"Growth in which the direction of the light is the determining factor, such as the growth of a plant toward a light source; turning or bending in response to light."},{"front":"recombinant DNA","back":"DNA formed either naturally or in the laboratory by the joining of segments of DNA from different sources. reduction [L. reductio, bringing back; originally “bringing back” a metal from"},{"front":"root pressure","back":"The pressure developed in roots as the result of osmosis, which causes guttation of water from leaves and exudation from cut stumps."},{"front":"solute potential","back":"The change in free energy or chemical potential of water produced by solutes; carries a negative (minus) sign. Also called solute potential."},{"front":"translocation","back":"(1) In plants, the long-distance transport of water, minerals, or food; most often used to refer to food transport; (2) in genetics, the interchange of chromosome segments between nonhomologous chromosomes."},{"front":"cohesion-tension theory","back":"A model for the ascent of water in vascular plants. According to this theory, water is pulled up through the plant body in the xylem. This pull, or tension, is brought about by transpiration and/or use of water by the leaves, which results in a gradient of water potential from the leaves to the soil solution at the surface of the roots."}]},{"chapter":31,"cards":[{"front":"climax community","back":"The final stage in a successional series; its nature is determined largely by the climate and soil of the region."},{"front":"community","back":"All the organisms inhabiting a common environment and interacting with one another."},{"front":"ecosystem","back":"A major interacting system that involves both living organisms and their physical environment."},{"front":"population","back":"Any group of individuals, usually of a single species, occupying a given area at the same time."},{"front":"mutualism","back":"The living together of two or more organisms in an association that is mutually advantageous."},{"front":"niche","back":"The role played by a particular species in its ecosystem."},{"front":"food chain, food web","back":"A chain or web of organisms existing in any natural community such that each link in a chain feeds on the one below and is eaten by the one above; there are seldom more than six links in a chain, with autotrophs on the bottom and the largest carnivores at the top."}]},{"chapter":32,"cards":[{"front":"biosphere","back":"The zone of air, land, and water at the surface of the Earth that is occupied by organisms."},{"front":"carbon cycle","back":"Worldwide circulation and utilization of carbon atoms."},{"front":"ecology","back":"The study of the interactions of organisms with their physical environment and with one other."},{"front":"tundra","back":"A treeless circumpolar region, best developed in the Northern Hemisphere and mostly found north of the Arctic Circle."}]}];
  const units = window.RAVEN_COURSE_DATA && window.RAVEN_COURSE_DATA.units;
  if (!units) return;
  const chapters = units.flatMap((unit) => unit.chapters || []);
  const existing = new Set(chapters.flatMap((chapter) => (chapter.vocabulary || []).map((card) => String(card[0]).trim().toLowerCase())));
  additions.forEach((entry) => {
    const chapter = chapters.find((item) => Number(item.number) === entry.chapter);
    if (!chapter) return;
    entry.cards.forEach((card, index) => {
      const key = card.front.trim().toLowerCase();
      if (existing.has(key)) return;
      existing.add(key);
      chapter.vocabulary.push([card.front, card.back]);
    });
  });
})();
